/* ============================================================
   ROUND 2 + ROUND 3 MOBILE SAFE-AREA ENFORCEMENT
   ------------------------------------------------------------
   Loaded AFTER globals.css from app/layout.tsx. Purely additive.
   Adopts the Facebook pattern site-wide: nothing renders behind
   the iPhone Dynamic Island / notch (top) or the home-indicator
   pill (bottom). Round 3 makes the catch-all NUCLEAR — it covers
   BOTH `position: fixed` AND `position: sticky`, BOTH top:0 and
   bottom:0 and inset:0 patterns, on EVERY viewport size (iPad
   PWA standalone with notch matters too), and uses !important to
   beat inline styles.
   ============================================================ */

/* ---------- ROUND 2: TARGETED COMPONENT CATCH-ALLS ---------- */

.modal-overlay,
[data-modal-overlay],
[role="dialog"][aria-modal="true"] {
  padding-top: max(var(--space-4, 16px), var(--safe-top, 0px));
  padding-bottom: max(var(--space-4, 16px), var(--safe-bottom, 0px));
  padding-left: max(var(--space-4, 16px), var(--safe-left, 0px));
  padding-right: max(var(--space-4, 16px), var(--safe-right, 0px));
}

.app-sticky-top,
[data-sticky-top] {
  top: var(--safe-top, 0px);
  padding-top: max(8px, var(--safe-top, 0px));
}
.app-bottom-bar {
  padding-bottom: max(12px, var(--safe-bottom, 0px));
}

.messenger-main [data-composer],
.messenger-main form[data-composer-form],
.messenger-main .msg-composer,
.msg-composer,
.messenger-shell .msg-composer,
.messenger-shell [data-composer],
.messenger-shell form[data-composer-form] {
  padding-bottom: max(12px, var(--safe-bottom, 0px)) !important;
}

.messenger-shell,
.messenger-sidebar,
.messenger-main,
.messenger-layout-root {
  max-width: 100vw;
  min-width: 0;
}

@media (max-width: 768px) {
  main, [role="main"], .admin-layout > main, .dashboard-main {
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-y: contain;
  }
  [role="dialog"] .card,
  [role="dialog"] .card-metal,
  .modal-overlay > div,
  [data-modal-overlay] > div {
    max-height: 88dvh !important;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }
}

.pnl-safe-page {
  padding-top: var(--safe-top, 0px);
  padding-bottom: var(--safe-bottom, 0px);
  padding-left: var(--safe-left, 0px);
  padding-right: var(--safe-right, 0px);
}

/* ============================================================
   ROUND 3 — NUCLEAR INLINE-STYLE ENFORCEMENT
   ============================================================ */

[style*="position: fixed"][style*="top: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="top: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="top:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="top:0"]:not([data-no-safe-area]),
[style*="position: sticky"][style*="top: 0"]:not([data-no-safe-area]),
[style*="position:sticky"][style*="top: 0"]:not([data-no-safe-area]),
[style*="position: sticky"][style*="top:0"]:not([data-no-safe-area]),
[style*="position:sticky"][style*="top:0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset:0"]:not([data-no-safe-area]) {
  padding-top: max(0px, var(--safe-top, 0px)) !important;
}

[style*="position: fixed"][style*="bottom: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="bottom: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="bottom:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="bottom:0"]:not([data-no-safe-area]),
[style*="position: sticky"][style*="bottom: 0"]:not([data-no-safe-area]),
[style*="position:sticky"][style*="bottom: 0"]:not([data-no-safe-area]),
[style*="position: sticky"][style*="bottom:0"]:not([data-no-safe-area]),
[style*="position:sticky"][style*="bottom:0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset:0"]:not([data-no-safe-area]) {
  padding-bottom: max(0px, var(--safe-bottom, 0px)) !important;
}

[style*="position: fixed"][style*="left: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="left: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="left:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="left:0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset:0"]:not([data-no-safe-area]) {
  padding-left: max(0px, var(--safe-left, 0px)) !important;
}

[style*="position: fixed"][style*="right: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="right: 0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="right:0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="right:0"]:not([data-no-safe-area]),
[style*="position: fixed"][style*="inset: 0"]:not([data-no-safe-area]),
[style*="position:fixed"][style*="inset:0"]:not([data-no-safe-area]) {
  padding-right: max(0px, var(--safe-right, 0px)) !important;
}

[data-cart-drawer],
.pnl-cart-drawer {
  padding-top: var(--safe-top, 0px);
  padding-bottom: var(--safe-bottom, 0px);
}

[data-dashboard-drawer],
.pnl-dashboard-drawer {
  padding-top: var(--safe-top, 0px);
  padding-bottom: var(--safe-bottom, 0px);
}

[style*="top: 60"][style*="position: fixed"]:not([data-no-safe-area]),
[style*="top:60"][style*="position:fixed"]:not([data-no-safe-area]) {
  top: var(--nav-offset, 60px) !important;
}

[data-toast-region],
.sonner-toaster,
[data-sonner-toaster] {
  padding-bottom: max(0px, var(--safe-bottom, 0px)) !important;
}

.full-screen-overlay,
[data-full-screen-overlay],
.app-drawer,
[data-drawer] {
  padding-top: max(0px, var(--safe-top, 0px)) !important;
  padding-bottom: max(0px, var(--safe-bottom, 0px)) !important;
  padding-left: max(0px, var(--safe-left, 0px)) !important;
  padding-right: max(0px, var(--safe-right, 0px)) !important;
}

[style*="position: fixed"][style*="inset: 0"],
[style*="position:fixed"][style*="inset:0"],
[style*="position: fixed"][style*="left: 0"][style*="right: 0"],
[style*="position:fixed"][style*="left:0"][style*="right:0"] {
  max-width: 100vw;
}

.sf-nav,
nav.sf-nav,
header.sf-nav {
  height: calc(60px + var(--safe-top, 0px)) !important;
  padding-top: var(--safe-top, 0px) !important;
  position: sticky !important;
  top: 0 !important;
}
@media (min-width: 600px) {
  .sf-nav,
  nav.sf-nav,
  header.sf-nav {
    height: calc(68px + var(--safe-top, 0px)) !important;
  }
}

.impersonation-banner,
[data-impersonation-banner] {
  padding-top: max(8px, var(--safe-top, 0px)) !important;
}
.stale-browser-banner,
[data-stale-browser-banner] {
  padding-top: max(8px, var(--safe-top, 0px)) !important;
}

/* ============================================================
   ROUND 4 — FACEBOOK-STYLE MOBILE BASELINE
   ============================================================ */

:root {
  color-scheme: light dark;
}

input, textarea, select,
.form-input {
  font-size: max(16px, 1rem) !important;
}

@media (min-width: 769px) and (pointer: fine) {
  input, textarea, select,
  .form-input {
    font-size: 0.95rem !important;
  }
}

@media (pointer: coarse) {
  .btn, button, [role="button"],
  input[type="button"], input[type="submit"],
  a.btn, a.btn-primary, a.btn-secondary, a.btn-ghost {
    min-height: 44px;
    min-width: 44px;
  }
  .icon-btn {
    min-width: 44px;
    min-height: 44px;
  }
  [role="listitem"] > a,
  .list-row,
  .conv-list [role="listitem"] {
    min-height: 56px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

nav, header, footer, .btn, button, [role="button"],
.tab-bar, .icon-btn, [role="navigation"] {
  -webkit-touch-callout: none;
}

[data-scroll-container] {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

[data-bottom-action-bar] {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  padding: 12px 16px;
  padding-bottom: max(12px, var(--safe-bottom, 0px));
  background: var(--surface-1, #0F1923);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.has-bottom-bar {
  padding-bottom: calc(72px + var(--safe-bottom, 0px));
}

.tap-target {
  display: block;
  min-height: 44px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.skeleton {
  background: linear-gradient(
    90deg,
    var(--surface-2, #162230) 0%,
    var(--surface-3, #1D2D3E) 50%,
    var(--surface-2, #162230) 100%
  );
  background-size: 200% 100%;
  animation: skeleton-pulse 1.5s ease-in-out infinite;
  border-radius: 8px;
}
@keyframes skeleton-pulse {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

img {
  max-width: 100%;
  height: auto;
}

:focus:not(:focus-visible) { outline: none; }
:focus-visible {
  outline: 2px solid var(--teal, #00C4BC);
  outline-offset: 2px;
}

p, span, div, h1, h2, h3, h4, h5, h6 {
  overflow-wrap: anywhere;
}

.aspect-square { aspect-ratio: 1 / 1; }
.aspect-video { aspect-ratio: 16 / 9; }
.aspect-portrait { aspect-ratio: 9 / 16; }
.aspect-photo { aspect-ratio: 4 / 3; }

[data-virtualized-row] {
  content-visibility: auto;
  contain-intrinsic-size: 0 80px;
}

/* ============================================================
   ROUND 5 — NUCLEAR HORIZONTAL OVERFLOW PREVENTION
   ============================================================ */

.pnl-navbar,
nav.pnl-navbar,
.sf-nav,
nav.sf-nav,
header.sf-nav,
.glass-header,
nav.glass-header {
  max-width: 100vw !important;
  width: 100% !important;
  overflow: hidden !important;
  box-sizing: border-box !important;
}

.pnl-navbar > *,
.sf-nav > *,
.glass-header > * {
  min-width: 0 !important;
}

.pnl-navbar img:not(.dashboard-icon),
.sf-nav img:not(.dashboard-icon),
.glass-header img:not(.dashboard-icon),
.nav img:not(.dashboard-icon) {
  max-width: 36px !important;
  max-height: 36px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  flex-shrink: 0 !important;
}

html, body {
  max-width: 100vw !important;
  overflow-x: hidden !important;
  box-sizing: border-box !important;
}

#__next,
[data-nextjs-scroll-focus-boundary],
body > div {
  max-width: 100vw !important;
  overflow-x: hidden !important;
}

.impersonation-banner,
.stale-browser-banner,
[data-impersonation-banner],
[data-stale-browser-banner] {
  max-width: 100vw !important;
  overflow: hidden !important;
  box-sizing: border-box !important;
}

.nav-display-name {
  max-width: clamp(80px, 30vw, 130px) !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

body > * {
  max-width: 100vw !important;
}

.sf-page-wrapper,
[data-storefront-page] {
  max-width: 100vw !important;
  overflow-x: hidden !important;
}

/* ============================================================
   ROUND 6 — MOBILE TABLE + FILTER CHIP RESPONSIVE LAYOUT
   ------------------------------------------------------------
   User report: My Researchers table, Product Catalog Manager
   filter chips, and product detail rows break character-by-
   character vertically on iPhone because their grid/flex
   columns are too narrow at 375-430px viewports.
   ============================================================ */
@media (max-width: 768px) {
  table {
    display: block;
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
    max-width: 100vw;
    white-space: nowrap;
  }
  table thead,
  table tbody {
    display: table;
    width: 100%;
    min-width: 480px;
  }
  table th,
  table td {
    white-space: nowrap;
    word-break: keep-all;
    min-width: 80px;
    padding: 8px 12px !important;
  }
  table td button,
  table td a {
    white-space: nowrap;
    font-size: 0.78rem;
  }

  .filter-chips,
  [data-filter-chips],
  [role="tablist"] {
    flex-wrap: wrap !important;
    gap: 4px !important;
  }
  .filter-chips > *,
  [data-filter-chips] > *,
  [role="tablist"] > * {
    flex-shrink: 0 !important;
    white-space: nowrap !important;
  }

  .metal-embossed-panel {
    flex-wrap: wrap !important;
  }
  .metal-embossed-panel > * {
    min-width: 0 !important;
    word-break: normal !important;
    overflow-wrap: anywhere !important;
  }
  .metal-embossed-panel span,
  .metal-embossed-panel div,
  .metal-embossed-panel button {
    word-break: normal !important;
    overflow-wrap: break-word !important;
    white-space: normal !important;
  }
  .metal-embossed-panel h4,
  .metal-embossed-panel strong {
    white-space: normal !important;
    word-break: keep-all !important;
    overflow-wrap: anywhere !important;
    min-width: 0;
  }
  .metal-embossed-panel input[type="checkbox"],
  .metal-embossed-panel button {
    flex-shrink: 0 !important;
  }
}

/* ============================================================
   ROUND 6 — MESSENGER HEADER DE-BLOAT
   ------------------------------------------------------------
   Round 2's safe-top padding-top inside the messenger conversation
   header was DOUBLE-counting with the layout's spacer above. Result:
   ~60px empty band that pushed Anna+icons way down the screen
   ("cut off" appearance). 12px is correct since the spacer above
   already reserves --nav-offset.
   ============================================================ */
.messenger-main header,
.messenger-main > div > header,
.messenger-shell header {
  padding-top: 12px !important;
}

/* ============================================================
   ROUND 7 — NAVBAR ICON RESIZE + MESSENGER TWO-PANE FIX
   + PRODUCT CATALOG MOBILE ROWS
   ------------------------------------------------------------
   Why this round exists:
   1. User reported Dashboard icon was being cut off on mobile.
      Root cause: dashboard-icon image renders at 158x74 inline.
      On a 375px iPhone, hamburger(36) + back(36) + divider +
      bells + dashboard(158) + username(130) overflows by ~100px.
      Fix: shrink all top-bar icons on <=768px so the row fits.
   2. User reported messenger conversation list and conversation
      view both visible/cut off on mobile. Root cause: the CSS
      mobile two-pane slide rules (globals.css 1867-1932)
      required .messenger-shell + .msg-panel-active classes but
      MessengerShell.tsx only set .has-active on the aside.
      The classes are NOW added on the root in MessengerShell.tsx,
      this Round 7 block adds the overrides those rules need
      (notably !important on sidebar width=100% so it overrides
      the inline width:320 set when activeId is truthy).
   3. Product Catalog filter chips and product rows still
      character-wrapped because Round 6's span overrides used
      white-space:normal which lets short labels break mid-word
      in narrow flex containers. Round 7 keeps short labels
      on one line and forces parent flex containers to wrap so
      siblings move to a new row instead of compressing.
   ============================================================ */

/* --- (1) NAVBAR — shrink all top-bar icons on mobile --- */
@media (max-width: 768px) {
  /* The dashboard image is the biggest offender — 158x74 inline.
     Cap by width; height: auto preserves the 2:1 aspect ratio. */
  .pnl-navbar a img.dashboard-icon {
    width: 56px !important;
    max-width: 56px !important;
    height: auto !important;
  }
  /* Hamburger icon — was 36x36 */
  .pnl-navbar img[alt="Menu"] {
    width: 28px !important;
    height: 28px !important;
  }
  /* Hide username completely on phones (no room) */
  .pnl-navbar .nav-display-name {
    display: none !important;
  }
  /* Bells + back arrow — tighten padding so they don't waste width */
  .pnl-navbar button {
    padding: 2px !important;
  }
  /* Tighten the right-cluster gap so icons sit closer together */
  .pnl-navbar > div:last-child {
    gap: 4px !important;
  }
}

/* On very small phones (iPhone SE / 360px Android) go even smaller. */
@media (max-width: 380px) {
  .pnl-navbar a img.dashboard-icon {
    width: 48px !important;
    max-width: 48px !important;
  }
}

/* --- (2) MESSENGER — mobile two-pane slide works only when
       the sidebar width override beats the inline width:320 --- */
@media (max-width: 768px) {
  .messenger-shell .messenger-sidebar {
    width: 100% !important;
    max-width: 100% !important;
  }
  .messenger-shell .messenger-main {
    width: 100% !important;
  }
  /* Conversation list: when active, hide; when idle, show full screen. */
  .messenger-shell.msg-panel-active .messenger-sidebar {
    pointer-events: none !important;
  }
  /* The back button inside the message pane — make tappable, 44pt. */
  .messenger-back-btn {
    min-height: 44px !important;
    padding: 10px 14px !important;
    font-size: 0.95rem !important;
  }
}

/* --- (3) PRODUCT CATALOG MANAGER — readable rows on mobile --- */
@media (max-width: 768px) {
  /* Keep short labels on one line; only let the product name wrap. */
  .metal-embossed-panel span {
    word-break: keep-all !important;
    overflow-wrap: normal !important;
    white-space: nowrap !important;
  }
  /* Allow the long product name to wrap (it's the 0.95rem 700-weight
     span on the first text line) — restore word-wrapping for it only. */
  .metal-embossed-panel span[style*="0.95rem"][style*="font-weight: 700"],
  .metal-embossed-panel span[style*="font-size: 1rem"],
  .metal-embossed-panel strong {
    white-space: normal !important;
    overflow-wrap: break-word !important;
    word-break: normal !important;
  }
  /* The product row wrapper (display:flex; align-items:center; gap:var(--space-4))
     — let the image+arrows wrap above the info, info above the toggle. */
  .metal-embossed-panel > div[style*="display: flex"][style*="align-items: center"] {
    flex-wrap: wrap !important;
    gap: 8px !important;
  }
  /* Info column inside the row (it has flex:1, min-width:0) must take
     full width when the row wraps. */
  .metal-embossed-panel > div[style*="align-items: center"] > div[style*="flex: 1"] {
    flex-basis: 100% !important;
    min-width: 0 !important;
  }
  /* The inner name/size/category and price lines should also wrap. */
  .metal-embossed-panel > div[style*="align-items: center"] > div[style*="flex: 1"] > div[style*="display: flex"] {
    flex-wrap: wrap !important;
    gap: 6px !important;
  }
  /* The view-mode and filter chips containers (flat/by category, all/active/hidden):
     these were the character-wrapping chips. Force them to be a single
     scrollable row instead of stacking per character. */
  .metal-frame .metal-content > div[style*="justify-content: space-between"] {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 12px !important;
  }
  .metal-frame .metal-content > div[style*="justify-content: space-between"] > div[style*="gap: 8"] {
    width: 100% !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
    flex-wrap: nowrap !important;
    padding-bottom: 4px !important;
  }
  .metal-frame .metal-content > div[style*="justify-content: space-between"] > div[style*="gap: 8"] > div {
    flex-shrink: 0 !important;
  }
  .metal-frame .metal-content > div[style*="justify-content: space-between"] > div[style*="gap: 8"] > div > button {
    flex-shrink: 0 !important;
    white-space: nowrap !important;
  }
  /* Bulk margin row — the Apply Bulk Margin row needs to wrap nicely too */
  .metal-content > h4 + div[style*="display: flex"][style*="flex-wrap: wrap"] {
    gap: 10px !important;
  }
  .metal-content > h4 + div[style*="display: flex"] button[class*="btn-neon-cyan"] {
    margin-left: 0 !important;
    width: 100% !important;
  }
}

/* ============================================================
   ROUND 8 — NAV NORMALIZATION + MESSENGER FULL-FIT
   ------------------------------------------------------------
   1. Round 7 over-shrunk the Dashboard icon (56px / 48px) which
      left the navbar looking lopsided. Now that the message and
      notification bells have moved LEFT of the spacer in
      Navbar.tsx, all five icons distribute across the row and
      the Dashboard icon can render at a normalized prominent
      size (88px on most phones, 72px on iPhone SE / 360px).
   2. The in-content "Conversations" back row was REMOVED from
      MessengerShell.tsx. We also hide .messenger-back-btn here
      as defense in depth in case another descendant ever sets
      that class.
   3. The conversation view on mobile cut off the composer's
      Send button and pushed the thread off-screen. This round
      shrinks the conversation header padding, message bubble
      font, composer padding, and per-message margins so the
      header + thread + composer (with Send) all fit in the
      visual viewport. Bubble max-width grows from 65% to 82%
      on mobile so short messages don't waste horizontal space.
   ============================================================ */

/* --- (1) NAVBAR — normalize Dashboard icon, override Round 7 caps --- */
@media (max-width: 768px) {
  .pnl-navbar a img.dashboard-icon {
    width: 88px !important;
    max-width: 88px !important;
    height: auto !important;
  }
}
@media (max-width: 380px) {
  .pnl-navbar a img.dashboard-icon {
    width: 72px !important;
    max-width: 72px !important;
  }
}

/* --- (2) MESSENGER — defensive: hide any stray back row --- */
.messenger-back-btn {
  display: none !important;
}

/* --- (3) MESSENGER conversation view — compact on mobile so the
       entire header + thread + composer (with Send button) fits --- */
@media (max-width: 768px) {
  /* Tighten the conversation header (name + phone/video/info icons row) */
  .messenger-main > header,
  .messenger-main > div > header {
    padding: 8px 12px !important;
    gap: 8px !important;
    min-height: 48px !important;
  }
  .messenger-main > header img,
  .messenger-main > div > header img {
    width: 32px !important;
    height: 32px !important;
  }
  .messenger-main > header [aria-label],
  .messenger-main > div > header [aria-label] {
    padding: 4px !important;
  }

  /* Message bubble: wider envelope (more room on narrow phones),
     smaller font + tighter padding so more thread fits per screen. */
  .messenger-main [data-bubble],
  .messenger-main [role="article"],
  .messenger-main > div > div > div > div[style*="max-width: 65%"],
  .messenger-main div[style*="maxWidth: '65%'"] {
    max-width: 82% !important;
  }
  .messenger-main p,
  .messenger-main [data-bubble] p,
  .messenger-main [data-bubble] span:not([aria-hidden]) {
    font-size: 0.84rem !important;
    line-height: 1.35 !important;
  }
  .messenger-main [data-bubble] {
    padding: 6px 10px !important;
  }
  /* Day-separator (YESTERDAY AT 10:06 PM, etc.) — smaller and tighter */
  .messenger-main [data-day-separator],
  .messenger-main time {
    font-size: 0.62rem !important;
    margin: 8px 0 4px !important;
  }

  /* Composer (msg-composer) — tighten outer padding so the send
     button is comfortably above the iOS home-indicator. The
     existing safe-area padding stays via env(safe-area-inset-bottom). */
  .messenger-main .msg-composer,
  .msg-composer {
    padding: 6px 8px !important;
    padding-bottom: max(8px, env(safe-area-inset-bottom)) !important;
    border-top-width: 1px !important;
  }
  .messenger-main .msg-composer > div,
  .msg-composer > div {
    padding: 4px 8px !important;
    gap: 8px !important;
    border-top-width: 0 !important;
  }
  /* Send button itself — keep at 44pt touch target but no extra margin */
  .messenger-main .msg-composer button[aria-label="Send Message"],
  .msg-composer button[aria-label="Send Message"] {
    flex-shrink: 0 !important;
  }
}

/* ============================================================
   END ROUND 2 + ROUND 3 + ROUND 4 + ROUND 5 + ROUND 6 + ROUND 7
   + ROUND 8 MOBILE SAFE-AREA AND HORIZONTAL OVERFLOW ENFORCEMENT
   ============================================================ */

'use client';

import Link from 'next/link';
import Image from 'next/image';
import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import NavbarNotificationBell from '@/components/NavbarNotificationBell';
import MessageBell from '@/components/MessageBell';

/* ───────────────────────────────────────────── 
   Page title resolution — maps route prefixes
   to human-readable, title-case labels.
   ───────────────────────────────────────────── */
function resolveTitle(pathname: string, role: string): string {
  if (pathname === '/')               return 'Pep Nation Lab';
  if (pathname.startsWith('/admin/products')) return 'Product Catalog';
  if (pathname.startsWith('/admin/agents'))   return 'Agents';
  if (pathname.startsWith('/admin/orders'))   return 'Orders';
  if (pathname.startsWith('/admin/sales'))    return 'Sales & Revenue';
  if (pathname.startsWith('/admin/pricing'))  return 'Pricing';
  if (pathname.startsWith('/admin/researchers')) return 'Researchers';
  if (pathname.startsWith('/admin/invitations')) return 'Invitations';
  if (pathname.startsWith('/admin/commissions')) return 'Commissions';
  if (pathname.startsWith('/admin/coupons'))  return 'Coupons';
  if (pathname.startsWith('/admin/statements')) return 'Statements';
  if (pathname.startsWith('/admin/restock'))  return 'Wholesale Restock';
  if (pathname.startsWith('/admin/transactions')) return 'Transactions';
  if (pathname.startsWith('/admin/webhooks')) return 'Webhooks';
  if (pathname.startsWith('/admin/settings')) return 'Admin Settings';
  if (pathname.startsWith('/admin/audit'))    return 'Audit Log';
  if (pathname.startsWith('/admin/push'))     return 'Push Notifications';
  if (pathname.startsWith('/admin/moderation')) return 'Message Moderation';
  if (pathname.startsWith('/admin/messenger')) return 'Messenger';
  if (pathname.startsWith('/admin/subscriptions')) return 'Subscriptions';

  if (pathname.startsWith('/admin/scheduled-prices')) return 'Scheduled Prices';
  if (pathname.startsWith('/admin/store-credits')) return 'Store Credits';
  if (pathname.startsWith('/admin/store-preview')) return 'Store Preview';
  if (pathname.startsWith('/admin/referrals')) return 'Referrals';
  if (pathname.startsWith('/admin/sms'))      return 'SMS';
  if (pathname.startsWith('/admin'))          return 'Admin Dashboard';
  if (pathname.startsWith('/messenger'))      return 'Messenger';
  if (pathname.startsWith('/dashboard/agent')) return 'Agent Dashboard';
  if (pathname.startsWith('/dashboard'))      return 'Dashboard';
  if (pathname.startsWith('/products'))       return 'Products';
  if (pathname.startsWith('/about'))          return 'About';
  if (pathname.startsWith('/login'))          return 'Sign In';
  if (pathname.startsWith('/account'))        return 'Account';
  if (pathname.startsWith('/orders'))         return 'My Orders';
  if (pathname.startsWith('/checkout'))       return 'Checkout';
  if (pathname.startsWith('/shipping'))       return 'Shipping';
  if (pathname.startsWith('/invite'))         return 'Invitation';

  // Agent storefront slugs — single-segment paths
  const segments = pathname.split('/').filter(Boolean);
  if (segments.length === 1 && !pathname.startsWith('/api')) {
    if (role.includes('agent') || role === 'researcher') return 'Agent Storefront';
  }

  return 'Pep Nation Lab';
}

/* ───────────────────────────────────────────── 
   Mobile / slide-out nav drawer items
   ───────────────────────────────────────────── */
function DrawerLink({
  href,
  label,
  icon,
  onClick,
}: {
  href: string;
  label: string;
  icon: React.ReactNode;
  onClick: () => void;
}) {
  return (
    <Link
      href={href}
      onClick={onClick}
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--space-3)',
        padding: '12px var(--space-5)',
        color: 'var(--silver)',
        fontSize: '0.95rem',
        fontWeight: 500,
        textDecoration: 'none',
        borderLeft: '3px solid transparent',
        transition: 'all 0.15s',
        minHeight: 48,
      }}
      className="drawer-link"
    >
      <span style={{ display: 'inline-flex', opacity: 0.7 }}>{icon}</span>
      {label}
    </Link>
  );
}

const IP = { width: 18, height: 18, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };

export default function Navbar({ onMenuClick, isOpen, title }: { onMenuClick?: () => void; isOpen?: boolean; title?: string } = {}) {
  const router = useRouter();
  const pathname = usePathname();

  const [drawerOpen, setDrawerOpen] = useState(false);
  const [user, setUser] = useState<{ id: string; email?: string } | null>(null);
  const [profile, setProfile] = useState<{ full_name?: string | null; role?: string; referring_agent_id?: string | null } | null>(null);
  const [agentSlug, setAgentSlug] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);


  const role = profile?.role ?? 'researcher';
  const displayName = profile?.full_name || user?.email?.split('@')[0] || '';
  const pageTitle = resolveTitle(pathname, role);
  const finalTitle = title || pageTitle;
  const isMessenger = pathname.startsWith('/messenger');

  // Dashboard link based on role
  const dashLink = role === 'admin'
    ? '/admin'
    : role.includes('agent')
    ? '/dashboard/agent'
    : '/dashboard';
  const dashLabel = role === 'admin'
    ? 'Admin Dashboard'
    : role.includes('agent')
    ? 'Agent Dashboard'
    : 'Dashboard';

  const closeDrawer = useCallback(() => setDrawerOpen(false), []);

  // Lock body scroll when drawer is open
  useEffect(() => {
    document.body.style.overflow = drawerOpen ? 'hidden' : '';
    return () => { document.body.style.overflow = ''; };
  }, [drawerOpen]);

  // Close drawer on route change
  useEffect(() => {
    setDrawerOpen(false);
  }, [pathname]); // eslint-disable-line react-hooks/exhaustive-deps

  // Auth state
  useEffect(() => {
    const supabase = createClient();
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setUser({ id: session.user.id, email: session.user.email });
        supabase
          .from('profiles')
          .select('full_name, role, referring_agent_id')
          .eq('id', session.user.id)
          .maybeSingle()
          .then(({ data }) => {
            if (data) {
              setProfile(data);
              // If researcher, look up their agent's storefront slug
              if (data.role === 'researcher' && data.referring_agent_id) {
                supabase
                  .from('agent_profiles')
                  .select('slug')
                  .eq('id', data.referring_agent_id)
                  .maybeSingle()
                  .then(({ data: ap }) => { if (ap?.slug) setAgentSlug(ap.slug); });
              }
            }
            setLoading(false);
          });
      } else {
        setLoading(false);
      }
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_, session) => {
      if (session) {
        setUser({ id: session.user.id, email: session.user.email });
        supabase
          .from('profiles')
          .select('full_name, role, referring_agent_id')
          .eq('id', session.user.id)
          .maybeSingle()
          .then(({ data }) => {
            if (data) {
              setProfile(data);
              if (data.role === 'researcher' && data.referring_agent_id) {
                supabase
                  .from('agent_profiles')
                  .select('slug')
                  .eq('id', data.referring_agent_id)
                  .maybeSingle()
                  .then(({ data: ap }) => { if (ap?.slug) setAgentSlug(ap.slug); });
              }
            }
          });
      } else {
        setUser(null);
        setProfile(null);
        setAgentSlug(null);
      }
      setLoading(false);
    });
    return () => subscription.unsubscribe();
  }, []);


  const handleSignOut = async () => {
    const supabase = createClient();
    await supabase.auth.signOut();
    window.location.replace('/');
  };

  // ── Smart Hierarchical Back Button ───────────────────────────────────────
  // We conditionally use native browser history if available. If the user landed
  // on a deep link directly (empty history stack), we route them up the app hierarchy.
  const handleBack = () => {
    if (window.history.length > 1) {
      router.back();
      return;
    }

    // Fallback: Logical Parent Routes
    if (pathname.startsWith('/admin/')) {
      router.push('/admin');
    } else if (pathname.startsWith('/account/')) {
      router.push(dashLink);
    } else if (pathname.match(/^\/[^\/]+\/product\//)) {
      const slug = pathname.split('/')[1];
      router.push(`/${slug}/store`);
    } else {
      router.push(dashLink);
    }
  };

  const showBack = pathname !== '/';

  return (
    <>
      {/* ══════════════════════════════════════════
          HEADER BAR
      ══════════════════════════════════════════ */}
      <nav
        className="nav pnl-navbar"
        style={{
          position: 'fixed',
          top: 0, left: 0, right: 0,
          zIndex: 200,
          height: 60,
          background: 'var(--nav-bg)',
          backdropFilter: 'blur(20px)',
          WebkitBackdropFilter: 'blur(20px)',
          borderBottom: '1px solid var(--nav-border)',
          display: 'flex',
          alignItems: 'center',
          padding: '0 var(--space-3)',
          gap: 'var(--space-2)',
        }}
      >
        {/* LEFT: Hamburger */}
        <button
          onClick={() => onMenuClick ? onMenuClick() : setDrawerOpen(o => !o)}
          aria-label="Open Navigation Menu"
          style={{
            background: 'none',
            border: 'none',
            cursor: 'pointer',
            color: 'var(--silver)',
            padding: 4,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: 8,
            flexShrink: 0,
            transition: 'background 0.15s',
          }}
        >
          {(isOpen !== undefined ? isOpen : drawerOpen) ? (
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          ) : (
            <img src="/images/hamburger-icon.png" alt="Menu" width={36} height={36} style={{ display: 'block' }} />
          )}
        </button>

        {/* Back arrow */}
        {showBack && (
          <>
            <button
              onClick={handleBack}
              aria-label="Go Back"
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                color: 'var(--silver)',
                padding: 4,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: 8,
                flexShrink: 0,
              }}
            >
              <div style={{ width: 36, height: 36, overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ filter: 'drop-shadow(0px 2px 4px rgba(0,0,0,0.5))', transition: 'opacity 0.2s', display: 'block' }} onMouseEnter={e => (e.currentTarget.style.opacity = '0.8')} onMouseLeave={e => (e.currentTarget.style.opacity = '1')}>
                  <defs>
                    <linearGradient id="premium-metal-body" x1="0%" y1="0%" x2="0%" y2="100%">
                      <stop offset="0%" stopColor="#E2E8F0" />
                      <stop offset="40%" stopColor="#FFFFFF" />
                      <stop offset="60%" stopColor="#94A3B8" />
                      <stop offset="100%" stopColor="#64748B" />
                    </linearGradient>
                    <linearGradient id="premium-metal-edge" x1="0%" y1="0%" x2="0%" y2="100%">
                      <stop offset="0%" stopColor="#FFFFFF" />
                      <stop offset="100%" stopColor="#475569" />
                    </linearGradient>
                  </defs>
                  <path d="M11 5L3 12L11 19V15H21V9H11V5Z" fill="url(#premium-metal-body)" stroke="url(#premium-metal-edge)" strokeWidth="1" strokeLinejoin="round" />
                </svg>
              </div>
            </button>

            {/* Vertical divider */}
            <div style={{ width: 1, height: 22, background: 'var(--surface-3)', flexShrink: 0, marginLeft: 4 }} />
          </>
        )}

        {/* MIDDLE-LEFT: Bells — placed BEFORE the spacer so the messenger
            and notification icons fill the dead space that used to hold
            the page title. With Dashboard pinned to the right and bells
            to the left of the spacer, all 5 navbar icons distribute
            cleanly across the row at their natural sizes on mobile. */}
        {!loading && user && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 4, flexShrink: 0 }}>
            <MessageBell onViewAll={() => router.push('/messenger')} />
            <NavbarNotificationBell />
          </div>
        )}

        {/* CENTER: Spacer (page title removed per mobile-fit request —
            the truncated "M." / "S.." was cluttering the header on
            narrow phones and added no information the right-side icons
            don't already convey). */}
        <div style={{ flex: 1, minWidth: 0 }} aria-hidden="true" />

        {/* RIGHT: Actions */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', flexShrink: 0 }}>
          {loading ? (
            <div style={{ width: 36, height: 36, borderRadius: '50%', background: 'var(--surface-2)' }} className="skeleton" />
          ) : user ? (
            <>
              <Link href={dashLink} aria-label={dashLabel} style={{ display: 'flex', alignItems: 'center', padding: 8, transition: 'transform 0.2s', background: 'none' }} onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.05)'} onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}>
                <img
                  src={
                    role === 'admin' ? '/nav-icons/admin-dashboard.png' :
                    role.includes('agent') ? '/nav-icons/agent-dashboard.png' :
                    '/nav-icons/dashboard.png'
                  }
                  alt={dashLabel}
                  width={158}
                  height={74}
                  className="dashboard-icon"
                  style={{ width: 158, height: 'auto', objectFit: 'contain', display: 'block' }}
                />
              </Link>
              <div
                style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', cursor: 'pointer' }}
                onClick={() => setDrawerOpen(o => !o)}
                title={displayName}
              >
                <span
                  className="nav-display-name"
                  style={{
                    fontSize: '0.82rem',
                    fontWeight: 600,
                    color: 'var(--nav-title)',
                    maxWidth: 130,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {displayName}
                </span>
              </div>
            </>
          ) : (
            <>
              <Link href="/login" className="btn btn-ghost btn-sm">Sign In</Link>
            </>
          )}
        </div>
      </nav>

      {/* ══════════════════════════════════════════
          SLIDE-OUT DRAWER (global site nav — not shown when admin controls hamburger)
      ══════════════════════════════════════════ */}
      {/* Backdrop */}
      {!onMenuClick && drawerOpen && (
        <div
          onClick={closeDrawer}
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(5,10,15,0.6)',
            backdropFilter: 'blur(4px)',
            WebkitBackdropFilter: 'blur(4px)',
            zIndex: 300,
            animation: 'navBackdropIn 0.2s ease',
          }}
        />
      )}

      {/* Drawer panel — only rendered for non-admin pages */}
      {!onMenuClick && (
      <div
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          bottom: 0,
          width: 280,
          background: 'var(--black-2)',
          borderRight: '1px solid var(--nav-border)',
          zIndex: 400,
          display: 'flex',
          flexDirection: 'column',
          transform: drawerOpen ? 'translateX(0)' : 'translateX(-100%)',
          transition: 'transform 0.28s cubic-bezier(0.4,0,0.2,1)',
          overflowY: 'auto',
          boxShadow: drawerOpen ? '4px 0 40px rgba(0,0,0,0.6)' : 'none',
          willChange: 'transform',
        }}
      >
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--space-3)',
          padding: 'var(--space-4) var(--space-5)',
          borderBottom: '1px solid rgba(255,255,255,0.06)',
          minHeight: 64,
        }}>
          <Link href={dashLink} onClick={closeDrawer} style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', textDecoration: 'none' }}>
            <Image src="/logo-mark.svg" alt="Pep Nation Lab" width={32} height={32} priority />
            <span style={{ fontFamily: 'var(--font-brand)', fontSize: '0.95rem', fontWeight: 800, color: 'var(--teal)', letterSpacing: '0.08em' }}>
              PEP NATION LAB
            </span>
          </Link>
        </div>

        {/* User info in drawer */}
        {user && (
          <div style={{
            padding: 'var(--space-4) var(--space-5)',
            borderBottom: '1px solid rgba(255,255,255,0.06)',
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--space-3)',
          }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontWeight: 600, color: 'var(--white)', fontSize: '0.9rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {displayName}
              </div>
              <div style={{ fontSize: '0.72rem', color: 'var(--grey-400)', textTransform: 'capitalize' }}>
                {role.replace('_', ' ')}
              </div>
            </div>
          </div>
        )}

        {/* Navigation links */}
        <nav style={{ flex: 1, padding: 'var(--space-3) 0', paddingBottom: 'calc(var(--space-6) + env(safe-area-inset-bottom, 24px))' }}>
          {/* Common links */}
          <DrawerLink href={dashLink} label="Home" onClick={closeDrawer}
            icon={<svg {...IP}><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>}
          />
          {/* Products link — hidden for researchers (they use their agent's storefront) */}
          {role !== 'researcher' && (
            <DrawerLink href="/products" label="Products" onClick={closeDrawer}
              icon={<svg {...IP}><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>}
            />
          )}
          {/* Researchers see their agent's storefront instead */}
          {role === 'researcher' && agentSlug && (
            <DrawerLink href={`/${agentSlug}`} label="Visit Your Store" onClick={closeDrawer}
              icon={<svg {...IP}><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>}
            />
          )}
          <DrawerLink href="/about" label="About" onClick={closeDrawer}
            icon={<svg {...IP}><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>}
          />

          {user && (
            <>
              <div style={{ height: 1, background: 'rgba(255,255,255,0.06)', margin: 'var(--space-2) 0' }} />

              {/* Dashboard */}
              <DrawerLink href={dashLink} label={dashLabel} onClick={closeDrawer}
                icon={<svg {...IP}><rect x="3" y="3" width="7" height="9"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="16" width="7" height="5"/></svg>}
              />

              {/* Messenger — only shown when NOT on messenger page */}
              {!isMessenger && (
                <DrawerLink href="/messenger" label="Messenger" onClick={closeDrawer}
                  icon={<svg {...IP}><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>}
                />
              )}

              {/* Agent-specific */}
              {role.includes('agent') && (
                <>
                  <DrawerLink href="/dashboard/agent" label="My Store" onClick={closeDrawer}
                    icon={<svg {...IP}><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>}
                  />
                </>
              )}



              <DrawerLink href="/account/notification-preferences" label="Notification Preferences" onClick={closeDrawer}
                icon={<svg {...IP}><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>}
              />

              <div style={{ height: 1, background: 'rgba(255,255,255,0.06)', margin: 'var(--space-2) 0' }} />

              <button
                onClick={() => { closeDrawer(); handleSignOut(); }}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 'var(--space-3)',
                  padding: '12px var(--space-5)',
                  color: 'var(--red)',
                  fontSize: '0.95rem',
                  fontWeight: 500,
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  width: '100%',
                  textAlign: 'left',
                  minHeight: 48,
                }}
              >
                <svg {...IP} stroke="var(--red)"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
                Sign Out
              </button>
            </>
          )}

          {!user && !loading && (
            <>
              <div style={{ height: 1, background: 'rgba(255,255,255,0.06)', margin: 'var(--space-2) 0' }} />
              <DrawerLink href="/login" label="Sign In" onClick={closeDrawer}
                icon={<svg {...IP}><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>}
              />
            </>
          )}
        </nav>
      </div>
      )} {/* end !onMenuClick drawer panel */}


      <style>{`
        .pnl-navbar { }
        .drawer-link:hover {
          color: var(--teal) !important;
          background: rgba(192,184,168,0.07);
          border-left-color: var(--teal) !important;
        }
        @keyframes navBackdropIn {
          from { opacity: 0; }
          to   { opacity: 1; }
        }
        @media (max-width: 480px) {
          .nav-display-name { display: none !important; }
        }
      `}</style>
    </>
  );
}

'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import ConversationList from './ConversationList';
import MessagePane from './MessagePane';
import SearchBar from './SearchBar';
import NewConversationDialog from './NewConversationDialog';
import { useMessengerStore } from '@/stores/messengerStore';
import {
  subscribeMyIncomingMessages,
  unsubscribe,
  type IncomingMessageNotification,
} from '@/lib/messenger/realtime';
import { vibrateLight } from '@/lib/messenger/haptics';

interface Props {
  userId: string;
}

const PRESENCE_INTERVAL_MS = 30_000;

interface CachedPrefs {
  browser_push: boolean;
  mute_all: boolean;
}

export default function MessengerShell({ userId }: Props) {
  const setActive = useMessengerStore((s) => s.setActive);
  const activeId = useMessengerStore((s) => s.activeConversationId);
  const conversations = useMessengerStore((s) => s.conversations);

  const [composeOpen, setComposeOpen] = useState(false);

  // fix-46.1: react to ?compose=1 via useSearchParams so the dialog opens
  // even when the user is already mounted on /messenger and the URL changes
  // via client-side navigation (Next.js App Router does not remount the
  // component, so a useEffect([]) read of window.location.search misses
  // the change). After consuming the param we use router.replace() to
  // strip it; the resulting reactive run sees compose=null and bails out.
  const router = useRouter();
  const searchParams = useSearchParams();
  useEffect(() => {
    if (!searchParams) return;
    const v = searchParams.get('compose');
    if (v === '1' || v === 'true') {
      setComposeOpen(true);
      const params = new URLSearchParams(searchParams.toString());
      params.delete('compose');
      const qs = params.toString();
      router.replace(qs ? `/messenger?${qs}` : '/messenger', { scroll: false });
    }
  }, [searchParams, router]);

  const prefsRef = useRef<CachedPrefs>({ browser_push: false, mute_all: false });
  const activeIdRef = useRef<string | null>(null);

  const mutedConvIdsRef = useRef<Set<string>>(new Set());

  useEffect(() => {
    activeIdRef.current = activeId ?? null;
  }, [activeId]);

  useEffect(() => {
    const next = new Set<string>();
    conversations.forEach((c) => {
      if (c.is_muted) next.add(c.conversation_id);
    });
    mutedConvIdsRef.current = next;

    if (!activeId && conversations.length > 0) {
      if (typeof window !== 'undefined' && window.innerWidth > 768) {
        setActive(conversations[0].conversation_id);
      }
    }
  }, [conversations, activeId, setActive]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/messenger/notification-prefs', {
          method: 'GET',
          cache: 'no-store',
        });
        if (!res.ok) return;
        const json = (await res.json()) as {
          prefs?: { browser_push?: boolean | null; mute_all?: boolean | null };
        };
        if (cancelled) return;
        prefsRef.current = {
          browser_push: json.prefs?.browser_push === true,
          mute_all: json.prefs?.mute_all === true,
        };
      } catch { /* silent */ }
    })();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!userId) return;

    const allowConvIds = new Set<string>(conversations.map((c) => c.conversation_id));
    const ch = subscribeMyIncomingMessages(
      userId,
      (m: IncomingMessageNotification & { sender_id?: string }) => {
        if (m.sender_id === userId) return;
        if (activeIdRef.current === m.conversation_id) return;
        if (mutedConvIdsRef.current.has(m.conversation_id)) return;
        try { vibrateLight(); } catch {}
        if (prefsRef.current.browser_push && !prefsRef.current.mute_all) {
          try {
            if (typeof Notification !== 'undefined' && Notification.permission === 'granted') {
              new Notification('New Message', {
                body: (m.text ?? '').slice(0, 120) || 'You Have A New Message',
                tag: `pnl-msg-${m.conversation_id}`,
              });
            }
          } catch { /* silent */ }
        }
      },
      allowConvIds,
    );

    return () => { unsubscribe(ch); };
  }, [userId, conversations]);

  useEffect(() => {
    let cancelled = false;
    const ping = async () => {
      try {
        await fetch('/api/messenger/presence-ping', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: '{}',
          cache: 'no-store',
          keepalive: true,
        });
      } catch { /* silent */ }
    };
    void ping();
    const id = setInterval(() => { if (!cancelled) void ping(); }, PRESENCE_INTERVAL_MS);
    return () => { cancelled = true; clearInterval(id); };
  }, []);

  const handleNewConversation = useCallback(() => {
    setComposeOpen(true);
  }, []);

  // Mobile back-button integration:
  // The in-content "Conversations" back row is REMOVED. The global navbar
  // back button is the single back UX on mobile. We push a history entry
  // when a conversation is opened so the browser/system back triggers
  // popstate, which we intercept to clear activeId (showing the
  // conversation list again) instead of routing away from /messenger.
  // The next system back actually leaves /messenger.
  const pushedRef = useRef(false);
  useEffect(() => {
    if (typeof window === 'undefined') return;
    if (activeId && !pushedRef.current) {
      try {
        window.history.pushState({ pnlMessengerActive: activeId }, '');
        pushedRef.current = true;
      } catch { /* silent */ }
    } else if (!activeId && pushedRef.current) {
      // activeId was cleared programmatically (e.g. user picked another
      // conversation from the list); roll the synthetic entry off the
      // history stack so the stack stays clean.
      try {
        window.history.back();
      } catch { /* silent */ }
      pushedRef.current = false;
    }
  }, [activeId]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const onPop = () => {
      if (activeIdRef.current) {
        setActive(null);
        pushedRef.current = false;
      }
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [setActive]);

  return (
    <div
      className={`messenger-shell${activeId ? ' msg-panel-active' : ''}`}
      style={{ display: 'flex', height: '100dvh', minHeight: 0, background: 'var(--black, #050A0F)', overflow: 'hidden' }}
    >
      <aside
        style={{
          width: activeId ? 320 : '100%',
          maxWidth: '100%',
          flexShrink: 0,
          borderRight: '1px solid var(--surface-3, #1D2D3E)',
          display: 'flex',
          flexDirection: 'column',
          minHeight: 0,
        }}
        className={`messenger-sidebar${activeId ? ' has-active' : ''}`}
      >
        <SearchBar onNewConversation={handleNewConversation} />
        <ConversationList />
      </aside>
      <section
        style={{
          flex: 1,
          display: activeId ? 'flex' : 'none',
          flexDirection: 'column',
          minWidth: 0,
          minHeight: 0,
        }}
        className="messenger-main"
      >
        {activeId && (
          <MessagePane conversationId={activeId} selfId={userId} />
        )}
      </section>
      {composeOpen && (
        <NewConversationDialog selfId={userId} onClose={() => setComposeOpen(false)} />
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';

interface ProductInfo {
  name: string;
  description: string;
  image_url: string | null;
  category: string;
  in_stock: boolean;
  inventory_count: number;
  unit_size: string | null;
  unit_measure: string | null;
  base_cost?: number | null;
}

interface AgentProduct {
  id: string;
  agent_id: string;
  product_id: string;
  custom_name: string | null;
  custom_description: string | null;
  custom_image_url: string | null;
  retail_price: number;
  is_visible: boolean;
  is_on_sale: boolean;
  sale_price: number | null;
  sort_order: number;
  products: ProductInfo;
  /** Your cost price from PNL (base_cost × tier multiplier, per 10 vials) */
  agent_cost: number | null;
  /** The agent’s current tier key, e.g. ‘tier_1’ */
  agent_tier: string | null;
}

type FilterMode = 'all' | 'active' | 'hidden';

export default function AgentStoreProducts({ agentId }: { agentId: string }) {
  const [products, setProducts] = useState<AgentProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<FilterMode>('all');
  const [viewMode, setViewMode] = useState<'flat' | 'category'>('flat');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<AgentProduct>>({});
  const [saving, setSaving] = useState(false);
  const [bulkMargin, setBulkMargin] = useState('50');
  const [bulkSaving, setBulkSaving] = useState(false);
  const [reordering, setReordering] = useState(false);
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  useEffect(() => { fetchProducts(); }, [agentId]);

  async function fetchProducts() {
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/api/agent/products');
      const json = await res.json();
      if (res.ok) {
        const sorted = (json.data || []).sort((a: AgentProduct, b: AgentProduct) => {
          // Primary: canonical product name A→Z
          const nameA = (a.products?.name || '').toLowerCase().trim();
          const nameB = (b.products?.name || '').toLowerCase().trim();
          if (nameA < nameB) return -1;
          if (nameA > nameB) return 1;
          // Secondary: unit_size numerically smallest→largest (e.g. 10mg before 50mg before 500mg)
          const sizeA = parseFloat(a.products?.unit_size || '0') || 0;
          const sizeB = parseFloat(b.products?.unit_size || '0') || 0;
          return sizeA - sizeB;
        });
        setProducts(sorted);
        // Auto-expand all categories on first load
        const cats = new Set(sorted.map((p: AgentProduct) => p.products?.category || 'Other'));
        setExpandedCategories(cats as Set<string>);
      } else {
        setError(json.error || 'Failed To Load Products');
      }
    } catch (err: any) {
      setError(err.message || 'An Error Occurred');
    } finally {
      setLoading(false);
    }
  }

  // Toggle visibility
  async function toggleVisibility(product: AgentProduct) {
    try {
      const res = await fetch('/api/agent/products', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: product.id, is_visible: !product.is_visible }),
      });
      if (res.ok) {
        setProducts(prev => prev.map(p => p.id === product.id ? { ...p, is_visible: !p.is_visible } : p));
      }
    } catch {}
  }

  // Move product up/down
  async function moveProduct(productId: string, direction: 'up' | 'down') {
    const idx = products.findIndex(p => p.id === productId);
    if (idx === -1) return;
    if (direction === 'up' && idx === 0) return;
    if (direction === 'down' && idx === products.length - 1) return;

    const newProducts = [...products];
    const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
    [newProducts[idx], newProducts[swapIdx]] = [newProducts[swapIdx], newProducts[idx]];

    // Update sort_order values
    const reordered = newProducts.map((p, i) => ({ ...p, sort_order: i }));
    setProducts(reordered);

    // Save to DB
    setReordering(true);
    try {
      await fetch('/api/agent/products/reorder', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          order: reordered.map(p => ({ id: p.id, sort_order: p.sort_order }))
        }),
      });
    } catch {} finally {
      setReordering(false);
    }
  }

  // Edit
  function handleEdit(p: AgentProduct) {
    setEditingId(p.id);
    // Pre-fill with the product's current retail_price (per-10-unit stored value)
    // and back-compute markup % for the helper field.
    const existingMargin = (p as any).margin_percent != null
      ? Number((p as any).margin_percent)
      : p.agent_cost != null && p.agent_cost > 0 && p.retail_price > 0
        ? Math.round((p.retail_price / p.agent_cost - 1) * 100)
        : 50;
    setEditForm({
      id: p.id,
      custom_name: p.custom_name ?? '',
      custom_description: p.custom_description ?? '',
      custom_image_url: p.custom_image_url ?? '',
      retail_price: p.retail_price,   // stored as per-10-unit; displayed ÷10
      margin_percent: existingMargin,
      is_visible: p.is_visible,
      is_on_sale: p.is_on_sale,
      sale_price: p.sale_price,
    } as any);
  }

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    if (!editingId) return;

    // ── Hard rule: listed price can never be below agent cost ──────────────
    // retail_price and agent_cost are both stored as per-10-unit values.
    const listedPrice = Number((editForm as any).retail_price);
    const currentProduct = products.find(p => p.id === editingId);
    const agentCostPer10 = currentProduct?.agent_cost ?? 0;
    if (listedPrice < agentCostPer10) {
      alert(`Listed price cannot be below your cost ($${(agentCostPer10 / 10).toFixed(2)} / Vial). Please increase your price.`);
      return;
    }

    setSaving(true);
    try {
      const res = await fetch('/api/agent/products', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editForm),
      });
      if (!res.ok) {
        const json = await res.json();
        alert(json.error || 'Failed To Save');
      } else {
        await fetchProducts();
        setEditingId(null);
      }
    } catch (err: any) {
      alert(err.message);
    } finally {
      setSaving(false);
    }
  }

  async function handleBulkAdjust() {
    const margin = parseFloat(bulkMargin);
    if (isNaN(margin) || margin < 0) {
      alert('Please Enter A Valid Margin Percentage');
      return;
    }
    setBulkSaving(true);
    try {
      const res = await fetch('/api/agent/products/bulk-margin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ marginPercent: margin }),
      });
      if (!res.ok) throw new Error('Failed To Apply');
      await fetchProducts();
    } catch (err: any) {
      alert(err.message);
    } finally {
      setBulkSaving(false);
    }
  }

  function toggleCategory(cat: string) {
    setExpandedCategories(prev => {
      const next = new Set(prev);
      if (next.has(cat)) next.delete(cat); else next.add(cat);
      return next;
    });
  }

  // Filter
  const filtered = products.filter(p => {
    if (filter === 'active') return p.is_visible;
    if (filter === 'hidden') return !p.is_visible;
    return true;
  });

  // Group by category
  const grouped = filtered.reduce<Record<string, AgentProduct[]>>((acc, p) => {
    const cat = p.products?.category || 'Other';
    if (!acc[cat]) acc[cat] = [];
    acc[cat].push(p);
    return acc;
  }, {});
  const sortedCategories = Object.keys(grouped).sort();

  const activeCount = products.filter(p => p.is_visible).length;
  const hiddenCount = products.filter(p => !p.is_visible).length;

  if (loading) {
    return (
      <div style={{ padding: 'var(--space-8)', textAlign: 'center' }}>
        <p style={{ color: 'var(--teal)', fontSize: '1rem' }}>Loading Store Products...</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>
      {/* Header */}
      <div className="metal-frame">
        <div className="metal-content" style={{ padding: 'var(--space-6)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 'var(--space-4)' }}>
            <div>
              <h3 className="metal-text" style={{ fontSize: '1.25rem', margin: 0, fontFamily: 'var(--font-brand)', textTransform: 'uppercase', letterSpacing: '0.04em' }}>
                Product Catalog Manager
              </h3>
              <p style={{ color: 'rgba(255,255,255,0.4)', fontSize: '0.82rem', margin: '4px 0 0' }}>
                Toggle Products On/Off, Reorder Them, Set Custom Prices And Descriptions.
              </p>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              {/* View mode toggle */}
              <div style={{ display: 'flex', gap: 4, background: 'rgba(0,0,0,0.5)', borderRadius: '4px', padding: 3, border: '1px solid rgba(255,255,255,0.05)' }}>
                {( [['flat', 'All'], ['category', 'By Category']] as ['flat' | 'category', string][] ).map(([key, label]) => (
                  <button
                    key={key}
                    onClick={() => setViewMode(key)}
                    style={{
                      padding: '5px 12px', border: 'none', borderRadius: '4px', cursor: 'pointer',
                      fontSize: '0.75rem', fontWeight: 600, transition: 'all 0.2s',
                      background: viewMode === key ? 'rgba(0,229,255,0.1)' : 'transparent',
                      color: viewMode === key ? '#00E5FF' : 'rgba(255,255,255,0.4)',
                    }}
                  >
                    {label}
                  </button>
                ))}
              </div>
              <div style={{ display: 'flex', gap: 4, background: 'rgba(0,0,0,0.5)', borderRadius: '4px', padding: 3, border: '1px solid rgba(255,255,255,0.05)' }}>
              {( [['all', `All (${products.length})`], ['active', `Active (${activeCount})`], ['hidden', `Hidden (${hiddenCount})`]] as [FilterMode, string][] ).map(([key, label]) => (
                <button
                  key={key}
                  onClick={() => setFilter(key)}
                  style={{
                    padding: '6px 14px', border: 'none', borderRadius: '4px', cursor: 'pointer',
                    fontSize: '0.78rem', fontWeight: 600, transition: 'all 0.2s',
                    background: filter === key ? 'rgba(0,229,255,0.1)' : 'transparent',
                    color: filter === key ? '#00E5FF' : 'rgba(255,255,255,0.4)',
                  }}
                >
                  {label}
                </button>
              ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Bulk Margin */}
      <div className="metal-frame">
        <div className="metal-content" style={{ padding: 'var(--space-5)' }}>
          <h4 style={{ fontSize: '0.9rem', color: '#00E5FF', marginBottom: 'var(--space-3)', fontFamily: 'var(--font-brand)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Bulk Margin Adjustment</h4>
          <div style={{ display: 'flex', gap: 'var(--space-3)', alignItems: 'center', flexWrap: 'wrap' }}>
            <span style={{ fontSize: '0.82rem', color: 'rgba(255,255,255,0.4)' }}>Apply +</span>
            <input
              type="number"
              className="form-input"
              style={{ width: 80, padding: '4px 8px', height: 32, background: 'linear-gradient(180deg, #0b0f16 0%, #121822 100%)', border: '1px solid rgba(0,0,0,0.8)', boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.5)', color: '#fff' }}
              value={bulkMargin}
              onChange={e => setBulkMargin(e.target.value)}
            />
            <span style={{ fontSize: '0.82rem', color: 'rgba(255,255,255,0.4)' }}>% Margin To All Products</span>
            <button
              className="btn-neon-cyan"
              onClick={handleBulkAdjust}
              disabled={bulkSaving}
              style={{ marginLeft: 'auto', padding: '6px 16px', fontSize: '0.8rem' }}
            >
              {bulkSaving ? 'Applying...' : 'Apply Bulk Margin'}
            </button>
          </div>
        </div>
      </div>

      {error && (
        <div className="metal-embossed-panel" style={{ border: '1px solid rgba(229,62,62,0.3)', padding: 'var(--space-3)', fontSize: '0.85rem', color: '#FC8181' }}>
          {error}
        </div>
      )}

      {/* ── Flat alphabetical list (default) ── */}
      {viewMode === 'flat' && (
        <div className="metal-frame">
          <div className="metal-content" style={{ padding: 0, overflow: 'hidden' }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1px', background: 'rgba(255,255,255,0.05)' }}>
            {filtered.map((p, _idx) => {
              const displayName = p.custom_name || p.products.name;
              const isEditing = editingId === p.id;
              const sizeLabel = p.products.unit_size && p.products.unit_measure
                ? `${p.products.unit_size}${p.products.unit_measure}`
                : '';
              return (
                <div
                  key={p.id}
                  className="metal-embossed-panel"
                  style={{
                    padding: 'var(--space-4) var(--space-5)',
                    margin: 0,
                    borderRadius: 0,
                    borderLeft: 'none', borderRight: 'none',
                    opacity: p.is_visible ? 1 : 0.5,
                    transition: 'opacity 0.2s',
                  }}
                >
                  {isEditing ? (
                    <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
                      <div className="form-group" style={{ marginBottom: 0 }}>
                        <label className="form-label" style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.6)' }}>Custom Name</label>
                        <input type="text" className="form-input" style={{ background: 'linear-gradient(180deg, #0b0f16 0%, #121822 100%)', border: '1px solid rgba(0,0,0,0.8)', boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.5)', color: '#fff' }}
                          placeholder={p.products.name}
                          value={editForm.custom_name || ''}
                          onChange={e => setEditForm({ ...editForm, custom_name: e.target.value })} />
                      </div>

                      <div style={{ display: 'flex', gap: 'var(--space-3)', alignItems: 'flex-end' }}>
                        <div className="form-group" style={{ marginBottom: 0, flex: 1 }}>
                          <label className="form-label" style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.6)' }}>
                            Listed Price
                            <span style={{ fontWeight: 400, color: 'rgba(255,255,255,0.4)', marginLeft: 6, fontSize: '0.68rem' }}>$ / Vial</span>
                          </label>
                          <div style={{ position: 'relative' }}>
                            <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: '#00E5FF', fontWeight: 700, fontSize: '0.9rem', pointerEvents: 'none' }}>$</span>
                            <input
                              type="number"
                              step="0.01"
                              min={p.agent_cost != null ? (p.agent_cost / 10).toFixed(2) : '0'}
                              className="form-input"
                              style={{ paddingLeft: 26, background: 'linear-gradient(180deg, #0b0f16 0%, #121822 100%)', border: '1px solid rgba(0,0,0,0.8)', boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.5)', color: '#fff' }}
                              placeholder={(Number(editForm.retail_price) / 10).toFixed(2)}
                              value={Number((editForm as any).retail_price) >= 0 ? (Number((editForm as any).retail_price) / 10).toFixed(2) : ''}
                              onChange={e => {
                                const perVial = parseFloat(e.target.value) || 0;
                                const per10 = perVial * 10;
                                const newMargin = p.agent_cost && p.agent_cost > 0
                                  ? Math.round((per10 / p.agent_cost - 1) * 100)
                                  : (editForm as any).margin_percent ?? 50;
                                setEditForm({ ...editForm, retail_price: per10, margin_percent: newMargin } as any);
                              }}
                            />
                          </div>
