                              <button type="button" onClick={() => setEditingId(null)} className="btn-silver" style={{ padding: '6px 16px', fontSize: '0.85rem' }}>Cancel</button>
                            </div>
                          </form>
                        ) : (
                          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--space-4)' }}>
